/* v0.3 research-ready layer; loaded after frozen v0.2 scripts. */
let v03QuestionShownAt=null,v03FirstInteractionAt=null,v03AnswerChangedCount=0,v03CarryActiveMs=0,v03CarryWallMs=0,v03CarryInterruptionMs=0;
shell=function(content,options={}){const{compact=false,researchLocked=false}=options;const header=researchLocked?`<header class="topbar research-locked"><span class="brand" aria-label="SignalSafe Research"><span class="brand__mark">${icon("shield",26)}</span><span>SignalSafe Research</span></span></header>`:`<header class="topbar"><button class="brand" data-route="home" aria-label="回首頁"><span class="brand__mark">${icon("shield",26)}</span><span>SignalSafe</span></button><div class="topbar__right"><span class="offline-status" id="offlineStatus"><span></span>${navigator.onLine?"本機模式":"目前離線"}</span><button class="icon-button" data-route="data" aria-label="資料與隱私">${icon("lock",20)}</button></div></header>`;return `<div class="app-shell ${compact?"app-shell--compact":""} ${researchLocked?"research-locked":""}">${header}<main>${content}</main><footer class="footer"><span>${storageNotice()}</span><span>App ${APP_VERSION} · 題庫 ${QUESTION_BANK_VERSION}</span></footer></div>`;};
homeView=function(){const latest=state.sessions.at(-1),hasResume=Boolean(state.activeAssessment?.mode==="training");return shell(`<section class="hero"><div class="hero__copy"><p class="hero__eyebrow">給 16–18 歲學生的防詐決策訓練</p><h1>90 秒，練習在關鍵時刻<br><span>做對下一步。</span></h1><p class="hero__text">不是替你猜真假。SignalSafe 讓你練習先停下、找出最需要注意的地方，再改走官方查證。</p><div class="hero__actions"><button class="button button--primary button--large" data-action="start-quick">${icon("bolt",21)}開始 90 秒快練</button><button class="button button--secondary button--large" data-route="assessment-intro">${icon("brain",21)}完整能力訓練</button></div><button class="resume-link" data-route="emergency">${icon("siren",18)}我現在遇到可疑狀況</button>${hasResume?`<button class="resume-link" data-action="resume-assessment">繼續未完成的完整能力訓練 ${icon("arrow",18)}</button>`:""}</div><div class="hero__visual" aria-hidden="true"><div class="phone-demo"><div class="phone-demo__top"><span></span><span></span></div><div class="message-bubble message-bubble--incoming">可以幫我投票嗎？<br>只差 3 票，現在登入就好</div><div class="risk-chip">外部登入＋限時壓力</div><div class="decision-card"><span>${icon("shield",22)}</span><div><strong>先不要點連結</strong><small>用原聯絡方式向本人確認</small></div></div></div></div></section><section class="principles" aria-label="SignalSafe 三步驟"><article><span>01</span><div><h2>先停下</h2><p>停止點擊、登入、付款或提供資料。</p></div></article><article><span>02</span><div><h2>找重點</h2><p>看話術、來源、要求行為與金流。</p></div></article><article><span>03</span><div><h2>去查證</h2><p>回原 App、官網或公開聯絡方式。</p></div></article></section><section class="mode-grid"><article class="mode-card mode-card--primary"><div class="mode-card__icon">${icon("bolt",28)}</div><div><p class="mode-card__meta">快速練習</p><h2>90 秒快練</h2><p>快速練 3 個獨立情境，不會使用正式前後測題目。</p></div><button class="text-button" data-action="start-quick">開始快練 ${icon("arrow",17)}</button></article><article class="mode-card"><div class="mode-card__icon">${icon("brain",28)}</div><div><p class="mode-card__meta">完整學習</p><h2>完整能力訓練</h2><p>透過前測、情境訓練與後測，看看自己的判斷盲點。</p></div><button class="text-button" data-route="assessment-intro">查看流程 ${icon("arrow",17)}</button></article><article class="mode-card"><div class="mode-card__icon">${icon("chart",28)}</div><div><p class="mode-card__meta">本機紀錄</p><h2>我的學習盲點</h2><p>${latest?"查看最容易忽略的線索與最需要加強的下一步。":"完成訓練後，這裡會顯示你的判斷盲點。"}</p></div><button class="text-button" data-route="dashboard">查看紀錄 ${icon("arrow",17)}</button></article></section>`);};
startQuestionTimer=function(carry=null){questionStartedAt=performance.now();hiddenStartedAt=null;interruptedDuration=0;v03CarryActiveMs=Number(carry?.activeMs??0);v03CarryWallMs=Number(carry?.wallMs??0);v03CarryInterruptionMs=Number(carry?.interruptionMs??0);v03QuestionShownAt=carry?.questionShownAt??new Date().toISOString();v03FirstInteractionAt=carry?.firstInteractionAt??null;v03AnswerChangedCount=Number(carry?.answerChangedCount??0);const a=state.activeAssessment;if(a?.mode==="research"){a.events??=[];const q=currentAssessmentQuestion?.();a.events.push({type:carry?"question_resumed":"question_shown",at:new Date().toISOString(),phase:a.phase,questionId:q?.id??null});}};
elapsedMs=function(){const now=performance.now(),activeHidden=hiddenStartedAt?now-hiddenStartedAt:0;return Math.max(0,v03CarryActiveMs+now-questionStartedAt-interruptedDuration-activeHidden);};
function v03Wall(){return Math.max(0,v03CarryWallMs+performance.now()-questionStartedAt)}function v03Interrupt(){const activeHidden=hiddenStartedAt?performance.now()-hiddenStartedAt:0;return Math.max(0,v03CarryInterruptionMs+interruptedDuration+activeHidden)}function v03Carry(){return{activeMs:elapsedMs(),wallMs:v03Wall(),interruptionMs:v03Interrupt(),questionShownAt:v03QuestionShownAt,firstInteractionAt:v03FirstInteractionAt,answerChangedCount:v03AnswerChangedCount}}function v03Mark(changed=true){if(!changed)return;if(!v03FirstInteractionAt)v03FirstInteractionAt=new Date().toISOString();else v03AnswerChangedCount+=1;}
createResponse=function(question,selections,phase){const s=signalScores(selections.signalIds,question.correctSignalIds);return{id:crypto.randomUUID(),questionId:question.id,phase,constructId:question.constructId??null,surfaceScenario:question.surfaceScenario??null,formVersion:question.formVersion??null,selectedActionId:selections.actionId,correctActionIds:question.correctActionIds,isActionCorrect:question.correctActionIds.includes(selections.actionId),selectedJudgment:selections.judgment??null,correctJudgment:question.correctJudgment,isJudgmentCorrect:selections.judgment?selections.judgment===question.correctJudgment:false,selectedSignalIds:selections.signalIds,correctSignalIds:question.correctSignalIds,signalPrecision:s.precision,signalRecall:s.recall,signalF1:s.f1,confidence:selections.confidence??null,responseTimeMs:Math.round(v03Wall()),activeResponseTimeMs:Math.round(elapsedMs()),interruptionDurationMs:Math.round(v03Interrupt()),answerChangedCount:v03AnswerChangedCount,questionShownAt:v03QuestionShownAt,firstInteractionAt:v03FirstInteractionAt,wasInterrupted:v03Interrupt()>0,submittedAt:new Date().toISOString()};};
startQuick=function(){const questions=pickQuickQuestions(Date.now());currentFlow={type:"quick",id:crypto.randomUUID(),questions,index:0,responses:[],selections:{actionId:null,signalIds:[]},step:"answer",startedAt:new Date().toISOString()};route="quick";startQuestionTimer();render();};
quickView=function(){if(!currentFlow||currentFlow.type!=="quick")return homeView();const q=currentFlow.questions[currentFlow.index],total=currentFlow.questions.length,progress=((currentFlow.index+(currentFlow.step==="feedback"?1:0))/total)*100,selections=currentFlow.selections,response=currentFlow.responses.at(-1);if(currentFlow.step==="complete")return quickCompleteView();return shell(`<section class="flow-header"><button class="back-button" data-action="quit-flow">← 離開</button><div class="flow-header__center"><strong>90 秒快練</strong><span>第 ${currentFlow.index+1}／${total} 題</span></div><span class="timer-note">速度不計分</span></section><div class="progress" role="progressbar" aria-label="90 秒快練進度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(progress)}"><span style="width:${progress}%"></span></div><section class="question-layout"><article class="scenario-card"><div class="scenario-card__header"><span class="avatar">${q.senderLabel.slice(0,1)}</span><div><strong>${q.senderLabel}</strong><small>${q.category} · 模擬情境</small></div></div><div class="scenario-card__message"><strong>${q.title}</strong><p>${q.message}</p></div><p class="scenario-card__note">此為合成練習情境，不是真實帳號或連結。</p></article>${currentFlow.step==="answer"?`<div class="answer-panel"><div class="answer-block"><div class="answer-block__title"><span>1</span><div><h2>現在最安全的下一步是？</h2><p>先選下一步，不用急著判定真假。</p></div></div><div class="option-list">${q.actionOptions.map(o=>`<button class="option ${selections.actionId===o.id?"is-selected":""}" data-select-action="${o.id}" aria-pressed="${selections.actionId===o.id}"><span class="option__radio"></span><span>${o.label}</span></button>`).join("")}</div></div><div class="answer-block"><div class="answer-block__title"><span>2</span><div><h2>這則訊息裡，哪一點最需要你提高警覺？</h2><p>選出一個最值得先停下來確認的線索。</p></div></div><div class="signal-grid">${q.signalOptions.map(o=>`<button class="signal-option ${selections.signalIds.includes(o.id)?"is-selected":""}" data-select-signal="${o.id}" aria-pressed="${selections.signalIds.includes(o.id)}"><small>${SIGNAL_CATEGORY_LABELS[o.category]}</small><span>${o.label}</span></button>`).join("")}</div></div><button class="button button--primary button--full" data-action="submit-quick" ${!selections.actionId||selections.signalIds.length!==1?"disabled":""}>查看解析 ${icon("arrow",19)}</button></div>`:feedbackPanel(q,response,true)}</section>`,{compact:true});};
assessmentIntroView=function(){const hasResume=Boolean(state.activeAssessment?.mode==="training");return shell(`<section class="page-heading"><button class="back-button" data-route="home">← 回首頁</button><p>完整學習</p><h1>完整能力訓練</h1><span>前測 8 題 → 訓練 8 題 → 後測 8 題</span></section><section class="assessment-intro"><div class="assessment-intro__timeline"><article><span>01</span><div><h2>前測</h2><p>先記錄目前的判斷方式，不立即公布答案。</p></div><strong>8 題</strong></article><article><span>02</span><div><h2>情境訓練</h2><p>每題提供安全下一步、重要線索、原因、可能後果與獨立查證方式。</p></div><strong>8 題</strong></article><article><span>03</span><div><h2>後測</h2><p>使用不同表面情境，再練一次同樣的底層能力。</p></div><strong>8 題</strong></article></div><aside class="assessment-intro__aside"><div>${icon("lock",26)}<h2>匿名、本機保存</h2><p>不收姓名、學校或聯絡方式。分頁失焦時會扣除中斷時間。</p></div><ul><li>約 20–30 分鐘</li><li>速度不加分</li><li>可中途暫停並在本機繼續</li></ul>${hasResume?`<button class="button button--primary button--full" data-action="resume-assessment">繼續上次進度</button><button class="button button--ghost button--full" data-action="restart-assessment">重新開始</button>`:`<button class="button button--primary button--full" data-action="start-assessment">開始完整能力訓練</button>`}</aside></section>`);};
function v03PhaseIds(){return Object.fromEntries(["pre","training","post"].map(p=>[p,getQuestionsByPhase(p).map(q=>q.id)]))}function v03Event(type,extra={}){const a=state.activeAssessment;if(a?.mode!=="research")return;a.events??=[];a.events.push({type,at:new Date().toISOString(),phase:a.phase,...extra});}
startAssessment=function(restart=false,mode="training",participantId=null){const existing=state.activeAssessment,canResume=!restart&&existing&&existing.mode===mode;if(!canResume){const id=crypto.randomUUID(),phases=v03PhaseIds(),seed=`${participantId??state.anonymousUserId}:${id}`;state.activeAssessment={id,mode,researchSessionId:mode==="research"?id:null,participantId:mode==="research"?participantId:null,studyVersion:mode==="research"?STUDY_VERSION:null,formVersion:mode==="research"?RESEARCH_FORM_VERSION:"consumer-v0.3",seed,phase:"pre",phaseIndex:0,questionIndex:0,questionOrder:mode==="research"?buildResearchQuestionOrder(phases,seed):phases,responses:[],events:mode==="research"?[{type:"session_started",at:new Date().toISOString(),phase:"pre"}]:[],pauseCount:0,resumeCount:0,startedAt:new Date().toISOString(),selections:blankAssessmentSelections(),step:"answer",timingCarry:null};state=saveState(state);startQuestionTimer();}else{if(mode==="research"){existing.resumeCount=(existing.resumeCount??0)+1;v03Event("session_resumed");}const carry=existing.timingCarry??null;existing.timingCarry=null;state=saveState(state);startQuestionTimer(carry);}currentFlow={type:"assessment"};route="assessment";render();};
function v03Guide(){return `<div class="classification-guide" aria-label="三種判斷說明"><div><strong>有明顯風險</strong><br>現在就應停止危險操作</div><div><strong>資訊不足</strong><br>還不能確定，先查證</div><div><strong>目前較可信</strong><br>目前沒有明顯異常，但仍保持基本警覺</div></div>`;}
assessmentView=function(){const a=state.activeAssessment,q=currentAssessmentQuestion();if(!a||!q)return a?.mode==="research"?researchIntroView():assessmentIntroView();const locked=a.mode==="research",labels={pre:"前測",training:"訓練",post:"後測"},sel=a.selections??blankAssessmentSelections(),total=a.questionOrder[a.phase].length,overall=a.phaseIndex*8+a.questionIndex+(a.step==="feedback"?1:0),progress=(overall/24)*100,response=a.responses.at(-1);return shell(`<section class="flow-header"><button class="back-button" data-action="pause-assessment">← 暫停</button><div class="flow-header__center"><strong>${labels[a.phase]}</strong><span>${labels[a.phase]} ${a.questionIndex+1} / ${total}</span></div><span class="phase-badge phase-badge--${a.phase}">${labels[a.phase]}</span></section><div class="progress" role="progressbar" aria-label="${labels[a.phase]}進度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(progress)}"><span style="width:${progress}%"></span></div><section class="research-question"><article class="scenario-card scenario-card--wide"><div class="scenario-card__header"><span class="avatar">${q.senderLabel.slice(0,1)}</span><div><strong>${q.senderLabel}</strong><small>${q.category} · 模擬情境</small></div></div><div class="scenario-card__message"><strong>${q.title}</strong><p>${q.message}</p></div><p class="scenario-card__note">此為合成練習情境，不是真實帳號或連結。</p></article>${a.step==="feedback"?feedbackPanel(q,response,false):`<div class="research-form"><section class="research-step"><div class="research-step__heading"><span>1</span><div><h2>你會怎麼做？</h2><p>選出目前最安全的下一步。</p></div></div><div class="option-list option-list--compact">${q.actionOptions.map(o=>`<button class="option ${sel.actionId===o.id?"is-selected":""}" data-assessment-action="${o.id}" aria-pressed="${sel.actionId===o.id}"><span class="option__radio"></span><span>${o.label}</span></button>`).join("")}</div></section><section class="research-step"><div class="research-step__heading"><span>2</span><div><h2>這則訊息目前看起來如何？</h2><p>不是所有情境都能立刻確定。</p></div></div><div class="judgment-grid">${Object.entries(JUDGMENT_LABELS).map(([key,label])=>`<button class="judgment judgment--${key} ${sel.judgment===key?"is-selected":""}" data-assessment-judgment="${key}" aria-pressed="${sel.judgment===key}">${label}</button>`).join("")}</div>${v03Guide()}</section><section class="research-step"><div class="research-step__heading"><span>3</span><div><h2>哪些地方最需要注意？</h2><p>可複選。</p></div></div><div class="signal-grid">${q.signalOptions.map(o=>`<button class="signal-option ${sel.signalIds.includes(o.id)?"is-selected":""}" data-assessment-signal="${o.id}" aria-pressed="${sel.signalIds.includes(o.id)}"><small>${SIGNAL_CATEGORY_LABELS[o.category]}</small><span>${o.label}</span></button>`).join("")}</div></section><section class="research-step"><div class="research-step__heading"><span>4</span><div><h2>你有多確定？</h2><p>只要選最接近你的感覺。</p></div></div><div class="confidence-grid confidence-grid--three">${[[1,"不太確定"],[2,"有點確定"],[3,"很確定"]].map(([v,l])=>`<button class="confidence ${sel.confidence===v?"is-selected":""}" data-assessment-confidence="${v}" aria-pressed="${sel.confidence===v}"><strong>${v}</strong><span>${l}</span></button>`).join("")}</div></section><button class="button button--primary button--full" data-action="submit-assessment" ${!sel.actionId||!sel.judgment||sel.signalIds.length===0||!sel.confidence?"disabled":""}>提交這題 ${icon("arrow",19)}</button></div>`}</section>`,{compact:true,researchLocked:locked});};
function researchIntroView(){const active=state.activeAssessment?.mode==="research"?state.activeAssessment:null;return shell(`<section class="research-gate"><p class="hero__eyebrow">正式研究流程</p><h1>開始本次測試</h1><p>本次流程約 20–30 分鐘。資料只保存匿名代碼，請不要輸入姓名、學校、電話、Email、社群帳號或其他私人資料。</p><ul><li>前測 8 題：不立即公布答案</li><li>訓練 8 題：每題提供解析</li><li>後測 8 題：完成前不立即公布答案</li></ul>${active?`<div class="research-result-meta"><div><small>匿名代碼</small><strong>${active.participantId}</strong></div><div><small>目前進度</small><strong>${({pre:"前測",training:"訓練",post:"後測"})[active.phase]} ${active.questionIndex+1}/8</strong></div></div><button class="button button--primary button--full" data-action="resume-research">繼續本次測試</button>`:`<div class="research-field"><label for="participantId">匿名受測代碼</label><input id="participantId" inputmode="text" autocomplete="off" placeholder="例如 UT001"><small>只接受匿名代碼，例如 UT001、E001、DRYRUN-001。</small></div><label class="research-consent"><input id="researchConsent" type="checkbox"><span><strong>研究者已完成受試同意程序</strong><br><small>此勾選只確認外部程序已完成，網站本身不取代正式 consent。</small></span></label><button class="button button--primary button--full" data-action="start-research">開始本次測試</button>`}<p class="scenario-card__note">Research Mode 進行期間不提供 90 秒快練、緊急訓練、Dashboard 或其他教育內容，直到後測完成。</p></section>`,{researchLocked:true});}
function researchResultsView(){const s=state.sessions.find(x=>x.id===state.lastResearchSessionId&&x.mode==="research")??state.sessions.filter(x=>x.mode==="research").at(-1);if(!s)return researchIntroView();return shell(`<section class="completion-card"><div class="completion-card__icon">${icon("check",42)}</div><p class="completion-card__meta">正式流程完成</p><h1>本次測試已完成。</h1><p>研究資料仍只保存在這台裝置，請由研究者匯出後依研究 SOP 保存。</p><div class="research-result-meta"><div><small>匿名代碼</small><strong>${s.participantId}</strong></div><div><small>研究版本</small><strong>${s.studyVersion}</strong></div></div><div class="completion-card__actions"><button class="button button--primary" data-action="export-research-json">匯出研究 JSON</button><button class="button button--secondary" data-action="end-research">結束</button></div></section>`,{compact:true,researchLocked:true});}
finishAssessment=function(){const a=state.activeAssessment,s={id:a.id,mode:a.mode,researchSessionId:a.researchSessionId,participantId:a.participantId,studyVersion:a.studyVersion,formVersion:a.formVersion,seed:a.seed,pauseCount:a.pauseCount??0,resumeCount:a.resumeCount??0,events:a.events??[],startedAt:a.startedAt,completedAt:new Date().toISOString(),appVersion:APP_VERSION,questionBankVersion:QUESTION_BANK_VERSION,questionOrder:a.questionOrder,responses:a.responses};if(s.mode==="research")s.events.push({type:"session_completed",at:s.completedAt,phase:"post"});state.sessions.push(s);if(s.mode==="research")state.lastResearchSessionId=s.id;state.activeAssessment=null;state=saveState(state);currentFlow=null;route=s.mode==="research"?"research-results":"dashboard";render();};
render=function(){const token=captureFocusToken();let view;if(route==="home")view=homeView();else if(route==="quick")view=quickView();else if(route==="assessment-intro")view=assessmentIntroView();else if(route==="assessment")view=assessmentView();else if(route==="assessment-phase-complete")view=assessmentPhaseCompleteView(currentFlow?.completedPhase??"pre");else if(route==="dashboard")view=dashboardView();else if(route==="emergency")view=emergencyView();else if(route==="data")view=dataView();else if(route==="research-intro")view=researchIntroView();else if(route==="research-results")view=researchResultsView();else view=homeView();app.innerHTML=view;bindEvents();restoreFocusToken(token);};
bindEvents=function(){document.querySelectorAll("[data-route]").forEach(e=>e.addEventListener("click",()=>{const next=e.dataset.route;if(next==="home"&&currentFlow?.type==="quick")currentFlow=null;if(next!=="emergency"&&currentFlow?.type==="emergency")currentFlow=null;setRoute(next);}));document.querySelectorAll("[data-action]").forEach(e=>e.addEventListener("click",()=>handleAction(e.dataset.action)));document.querySelectorAll("[data-select-action]").forEach(e=>e.addEventListener("click",()=>{v03Mark(currentFlow.selections.actionId!==e.dataset.selectAction);currentFlow.selections.actionId=e.dataset.selectAction;render();}));document.querySelectorAll("[data-select-signal]").forEach(e=>e.addEventListener("click",()=>{const next=e.dataset.selectSignal;v03Mark(currentFlow.selections.signalIds[0]!==next);currentFlow.selections.signalIds=[next];render();}));document.querySelectorAll("[data-assessment-action]").forEach(e=>e.addEventListener("click",()=>{const next=e.dataset.assessmentAction;v03Mark(state.activeAssessment.selections.actionId!==next);state.activeAssessment.selections.actionId=next;state=saveState(state);render();}));document.querySelectorAll("[data-assessment-judgment]").forEach(e=>e.addEventListener("click",()=>{const next=e.dataset.assessmentJudgment;v03Mark(state.activeAssessment.selections.judgment!==next);state.activeAssessment.selections.judgment=next;state=saveState(state);render();}));document.querySelectorAll("[data-assessment-signal]").forEach(e=>e.addEventListener("click",()=>{v03Mark(true);const id=e.dataset.assessmentSignal,s=new Set(state.activeAssessment.selections.signalIds);s.has(id)?s.delete(id):s.add(id);state.activeAssessment.selections.signalIds=[...s];state=saveState(state);render();}));document.querySelectorAll("[data-assessment-confidence]").forEach(e=>e.addEventListener("click",()=>{const next=Number(e.dataset.assessmentConfidence);v03Mark(state.activeAssessment.selections.confidence!==next);state.activeAssessment.selections.confidence=next;state=saveState(state);render();}));document.querySelectorAll("[data-emergency-request]").forEach(e=>e.addEventListener("click",()=>{const s=new Set(currentFlow.answers.requests??[]),id=e.dataset.emergencyRequest;s.has(id)?s.delete(id):s.add(id);currentFlow.answers.requests=[...s];render();}));document.querySelectorAll("[data-emergency-official]").forEach(e=>e.addEventListener("click",()=>{currentFlow.answers.official=e.dataset.emergencyOfficial;render();}));const input=document.querySelector("#importFile");if(input)input.addEventListener("change",handleImport);};
handleAction=function(name){switch(name){case"start-quick":startQuick();break;case"submit-quick":{const q=currentFlow.questions[currentFlow.index];currentFlow.responses.push(createResponse(q,{...currentFlow.selections,judgment:null},"quick"));currentFlow.step="feedback";render();break}case"next-quick":if(currentFlow.index+1>=currentFlow.questions.length)currentFlow.step="complete";else{currentFlow.index+=1;currentFlow.selections={actionId:null,signalIds:[]};currentFlow.step="answer";startQuestionTimer()}render();break;case"finish-quick":finishQuick(true);break;case"quit-flow":if(confirm("要離開這次快練嗎？未完成的快練不會保存。"))finishQuick(false);break;case"start-assessment":startAssessment(false,"training");break;case"restart-assessment":if(confirm("要刪除未完成進度並重新開始嗎？"))startAssessment(true,"training");break;case"resume-assessment":startAssessment(false,"training");break;case"start-research":{const p=document.querySelector("#participantId")?.value?.trim(),consent=document.querySelector("#researchConsent")?.checked;if(!isValidParticipantId(p)){toast("請使用匿名代碼，例如 UT001。不要輸入姓名或聯絡資料。","error");break}if(!consent){toast("請先確認研究者已完成外部受試同意程序。","error");break}startAssessment(true,"research",p.toUpperCase());break}case"resume-research":startAssessment(false,"research",state.activeAssessment?.participantId);break;case"pause-assessment":{const a=state.activeAssessment;a.timingCarry=v03Carry();a.pauseCount=(a.pauseCount??0)+1;v03Event("session_paused",{questionId:currentAssessmentQuestion()?.id??null});state=saveState(state);currentFlow=null;route=a.mode==="research"?"research-intro":"home";render();break}case"submit-assessment":submitAssessmentQuestion();break;case"next-assessment":advanceAssessmentQuestion();break;case"continue-phase":continueAssessmentPhase();break;case"export-research-json":{const s=state.sessions.find(x=>x.id===state.lastResearchSessionId&&x.mode==="research")??state.sessions.filter(x=>x.mode==="research").at(-1);if(!s){toast("找不到已完成的研究場次","error");break}downloadFile(`signalsafe-research-${s.participantId}-${new Date().toISOString().slice(0,10)}.json`,buildResearchExport(s),"application/json");break}case"end-research":route="research-intro";render();break;case"emergency-next":currentFlow.step=2;render();break;case"emergency-back":currentFlow.step=1;render();break;case"emergency-result":currentFlow.step=3;render();break;case"restart-emergency":currentFlow={type:"emergency",step:1,answers:{}};render();break;case"export-json":downloadFile(`signalsafe-${new Date().toISOString().slice(0,10)}.json`,exportState(state),"application/json");break;case"export-csv":downloadFile(`signalsafe-${new Date().toISOString().slice(0,10)}.csv`,sessionsToCsv(state.sessions.filter(s=>s.mode!=="research")),"text/csv;charset=utf-8");break;case"clear-data":if(confirm("確定清除這台裝置上的所有 SignalSafe 資料？此操作無法復原。")){state=clearState();currentFlow=null;toast("本機資料已清除","success");render()}break;default:break;}};
advanceAssessmentQuestion=function(){const a=state.activeAssessment,total=a.questionOrder[a.phase].length;if(a.questionIndex+1>=total){currentFlow={type:"assessment",completedPhase:a.phase};route="assessment-phase-complete";state=saveState(state);render();return}a.questionIndex+=1;a.selections=blankAssessmentSelections();a.step="answer";a.timingCarry=null;state=saveState(state);startQuestionTimer();render();};
continueAssessmentPhase=function(){const completed=currentFlow.completedPhase;if(completed==="post"){finishAssessment();return}const next=completed==="pre"?"training":"post";state.activeAssessment.phase=next;state.activeAssessment.phaseIndex+=1;state.activeAssessment.questionIndex=0;state.activeAssessment.selections=blankAssessmentSelections();state.activeAssessment.step="answer";state.activeAssessment.timingCarry=null;v03Event("phase_started",{phase:next});state=saveState(state);currentFlow={type:"assessment"};route="assessment";startQuestionTimer();render();};
assessmentPhaseCompleteView=function(phase){const locked=state.activeAssessment?.mode==="research",labels={pre:"前測完成",training:"訓練完成",post:locked?"本次測試完成":"完整能力訓練完成"},desc={pre:"前測不公布答案。接下來進入訓練階段，每題會有完整解析。",training:"接下來使用不同情境進行後測，檢查是否能把原理用在新問題。",post:locked?"後測已完成。下一步只提供研究資料匯出，不顯示學習答案或 Dashboard。":"現在可以查看自己的學習盲點。"};return shell(`<section class="completion-card"><div class="completion-card__icon">${icon(phase==="post"?"chart":"check",42)}</div><p class="completion-card__meta">${phase==="post"?"24 題全部完成":"階段完成"}</p><h1>${labels[phase]}</h1><p>${desc[phase]}</p><button class="button button--primary" data-action="continue-phase">${phase==="post"?"完成本次流程":"進入下一階段"} ${icon("arrow",19)}</button></section>`,{compact:true,researchLocked:locked});};
if(new URLSearchParams(location.search).get("mode")==="research")route="research-intro";render();
